#!/usr/bin/env python3
"""Hand-written simulation challenges for lessons centrally about a simulation's idea. No model involved. Every condition is machine-checked.
A lesson that already has a simulation keeps it. Writes work/<book>/chNN/explore.json, merged by tools/assemble-pack.py."""
import json, os, subprocess, tempfile
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE)
t = lambda say, when, then: {'say': say, 'when': when, 'then': then}
ANGLE = ('angle', {}, 'Open and close an angle', [t('Open the arm until you make a right angle.', 'angle == 90', 'A right angle is exactly 90 degrees, like the corner of a page.'), t('Keep going and make a straight angle.', 'angle == 180', 'A straight angle is 180 degrees: two right angles together.'), t('Now go past straight.', 'angle > 180 and angle < 360', 'Bigger than 180 degrees is a reflex angle.')], 'The size of an angle is how far the arm has turned.')
ANGLE2 = ('angle', {}, 'Measure a turn', [t('Make an angle smaller than a right angle.', 'angle > 0 and angle < 90 and angle != 40', 'Less than 90 degrees is acute.'), t('Make one bigger than a right angle but less than straight.', 'angle > 90 and angle < 180', 'Between 90 and 180 degrees is obtuse.'), t('Turn all the way round.', 'angle == 360', 'A complete turn is 360 degrees.')], 'Angles are measured in degrees, and a full turn is 360.')
RECT_P = ('rectangle', {}, 'Change a rectangle', [t('Make the length 10.', 'l == 10', 'A longer side means a longer way round.'), t('Make a square with sides of 5.', 'l == 5 and b == 5', 'All four sides are equal, so the perimeter is 4 x 5 = 20.')], 'Perimeter is the distance all the way round.')
RECT_A = ('rectangle', {}, 'Build with squares', [t('Make a rectangle with an area of 12 square units.', 'l * b == 12', 'Rows times columns counts every square.'), t('Find a different rectangle with area 12.', 'l * b == 12 and l != 4 and l != 6', 'Different shapes can cover the same area.')], 'Area counts how many unit squares cover a shape.')
RECT_C = ('rectangle', {}, 'Same area, different perimeter', [t('Make 4 by 3.', 'l == 4 and b == 3', 'Area 12, perimeter 14.'), t('Make 6 by 2.', 'l == 6 and b == 2', 'Still area 12, but now perimeter 16.'), t('Make 12 by 1.', 'l == 12 and b == 1', 'Still area 12, but perimeter 26. Same area does not mean same perimeter.')], 'Area and perimeter measure different things.')
FRAC = ('fraction', {}, 'Share a bar', [t('Cut the bar into 8 equal parts.', 'd == 8', 'More parts means each part is smaller.'), t('Shade half of it.', 'd == 8 and n == 4', '4 out of 8 equal parts is one half.')], 'A fraction counts equal parts of a whole.')
FRAC_EQ = ('fraction', {}, 'Find equal fractions', [t('Make one half using 2 parts.', 'd == 2 and n == 1', '1/2 is 0.5.'), t('Make the same amount using 6 parts.', 'd == 6 and n == 3', '3/6 is also 0.5: the same amount with smaller pieces.'), t('Now use 10 parts.', 'd == 10 and n == 5', '5/10 is equal to 1/2 too.')], 'Equivalent fractions name the same amount.')
FRAC_MIX = ('fraction', {}, 'More than one whole', [t('Use 4 parts in each bar and shade 4.', 'd == 4 and n == 4', '4/4 is exactly one whole.'), t('Now shade 7.', 'd == 4 and n == 7', '7/4 is one whole and three quarters.')], 'A mixed fraction is wholes and a part.')
INT = ('integers', {}, 'Jump along the number line', [t('Start at 1 and add -5.', 'start == 1 and add == -5', 'You cross zero and land on -4.'), t('Start at -4 and add 4.', 'start == -4 and add == 4', 'A number and its opposite make zero.')], 'Adding a negative moves left, adding a positive moves right.')
BAL = ('balance', {'a': 2, 'b': 3, 'c': 11}, 'Balance the scale', [t('Try x = 2.', 'x == 2', 'The left side is too light: 7 is less than 11.'), t('Find the x that balances it.', 'x == 4', '2 x 4 + 3 = 11, so both sides are equal.')], 'An equation is a balance: both sides must be equal.')
PAT = lambda rule, title, a, b, take: ('pattern', {'rule': rule}, title, [t(*a), t(*b)], take)
PART_M = ('particles', {}, 'Heat and cool water', [t('Cool it until it freezes.', 'temp <= 0', 'Ice keeps its own shape: its particles stay in place.'), t('Warm it up to 40 degrees.', 'temp == 40', 'Liquid water flows and changes shape.')], 'Heating and cooling change the state of water.')
PART_S = ('particles', {}, 'The three states of water', [t('Make ice.', 'temp <= 0', 'Solid: it holds its shape.'), t('Warm it to 50 degrees.', 'temp == 50', 'Liquid: it flows.'), t('Boil it into a gas.', 'temp >= 100', 'Gas: it spreads through all the space.')], 'The same water can be a solid, a liquid or a gas.')
CIR = ('circuit', {}, 'Light the bulb', [t('Close the switch.', 'closed == 1', 'With no gap, current can flow and the bulb lights.'), t('Open it again.', 'closed == 0 and cells >= 1 and bulbs >= 2 or closed == 0 and cells == 2', 'A gap anywhere stops the current.')], 'Current flows only around a closed path.')
CIR2 = ('circuit', {}, 'Change the circuit', [t('Close the switch.', 'closed == 1', 'The bulb lights.'), t('Add a second bulb.', 'closed == 1 and bulbs == 2', 'Two bulbs share one cell, so they glow less.'), t('Add another cell.', 'closed == 1 and bulbs == 2 and cells == 2', 'More cells make them brighter.')], 'A switch opens or closes the path for current.')
PEN = ('pendulum', {}, 'Change the length', [t('Make the string 100 cm long.', 'len == 100', 'A long pendulum takes about 2 seconds for each swing.'), t('Make it 25 cm long.', 'len == 25', 'A shorter pendulum swings faster.')], 'The time period depends on the length of the pendulum.')
REF = ('reflection', {}, 'Bounce light off a mirror', [t('Make the ray come in at 60 degrees.', 'i == 60', 'It leaves at 60 degrees too.'), t('Shine it straight down the normal.', 'i == 0', 'It comes straight back.')], 'The angle going out always equals the angle coming in.')
DAY = ('daynight', {}, 'Spin the Earth', [t('Go to midnight.', 'hour == 0 or hour == 24', 'The place faces away from the Sun.'), t('Bring it to sunrise.', 'hour == 6', 'It turns into the sunlight.')], 'Day and night happen because the Earth spins.')
SEA = ('seasons', {}, 'Travel round the Sun', [t('Go to December.', 'month == 12', 'The north leans away from the Sun: winter there.'), t('Go to March.', 'month == 3', 'Neither half leans towards the Sun.')], 'The tilt of the Earth makes the seasons.')
MAG = ('magnets', {}, 'Bring two magnets together', [t('Flip the right magnet.', 'flip == 1', 'Like poles face each other and push apart.'), t('Flip it back and bring them close.', 'flip == 0 and gap <= 30', 'Unlike poles pull together, more strongly when close.')], 'Like poles repel and unlike poles attract.')
SCALE = ('mapscale', {}, 'Use a map scale', [t('Measure 4 cm on the map.', 'cm == 4', 'Multiply by the scale to get the real distance.'), t('At 25 km per cm, measure 8 cm.', 'km == 25 and cm == 8', '8 x 25 = 200 km on the ground.')], 'A scale turns distance on a map into distance on the ground.')
LAT = ('latlong', {}, 'Find places on the grid', [t('Move to the Equator.', 'lat == 0', 'Latitude 0 is the Equator.'), t('Move into the Southern Hemisphere.', 'lat < 0', 'South of the Equator, latitude is marked S.')], 'Latitude says how far north or south a place is.')
LON = ('latlong', {}, 'Cross the Prime Meridian', [t('Move to the Prime Meridian.', 'lon == 0', 'Longitude 0 runs through Greenwich.'), t('Move into the west.', 'lon < 0', 'West of Greenwich, longitude is marked W.')], 'Longitude says how far east or west a place is.')
TZ = ('timezone', {}, 'Travel through the time zones', [t('Go 15 degrees east of Greenwich.', 'lon == 15', 'At noon in Greenwich it is 1 pm here.'), t('Go 30 degrees west.', 'lon == -30', 'It is 10 am here: going west, clocks are behind.')], 'Each 15 degrees of longitude is one hour.')
TL = ('timeline', {'events': [{'year': -2, 'label': '2 BCE'}, {'year': 2, 'label': '2 CE'}]}, 'Walk from BCE into CE', [t('Move past 2 BCE.', 'y >= -2 and y < 2', 'In BCE, years count down towards the starting point.'), t('Move past 2 CE.', 'y >= 2', 'From 2 BCE to 2 CE is three years, because there is no year zero.')], 'BCE years count down and CE years count up.')
SYM = ('symmetry', {}, 'Count the lines of symmetry', [t('Make a shape with 6 sides.', 'n == 6', 'A regular hexagon has 6 lines of symmetry.'), t('Make a triangle.', 'n == 3', 'An equilateral triangle has 3.')], 'A regular shape has as many lines of symmetry as sides.')
ROT = ('rotation', {'arms': 3}, 'Turn the shape', [t('Turn it until it looks the same.', 'turn == 120', 'A turn of 120 degrees brings it back into a matching position.'), t('Keep turning until it matches again.', 'turn == 240', 'It matches at 120 and 240 degrees, and again at 360.')], 'The order of rotation counts how many times a shape matches itself in one full turn.')
DEC = ('decimal', {}, 'Build a decimal', [t('Make 1.05.', 'o == 1 and t == 0 and h == 5', 'The 0 holds the tenths place.'), t('Make 1.50.', 'o == 1 and t == 5 and h == 0', '5 tenths is more than 5 hundredths, so 1.50 is bigger.')], 'Each place is ten times the place to its right.')
BAR = ('bargraph', {}, 'Change the bars', [t('Make Wednesday the tallest bar.', 'c > a and c > b', 'The tallest bar shows the biggest count.'), t('Change the scale so one mark stands for 10.', 'scale == 10', 'A scale changes the marks, not the data.')], 'A bar graph lets us compare at a glance.')
SPD = ('speed', {}, 'Race two cars', [t('Make the two cars level.', 'a == b', 'Same speed, same distance in the same time.'), t('Make red twice as fast as blue.', 'a == 2 * b', 'In the same time, red goes twice as far.')], 'Speed is the distance covered in one unit of time.')
SHD = ('shadow', {}, 'Change a shadow', [t('Move the object close to the lamp.', 'd <= 15', 'The shadow grows large.'), t('Move it far from the lamp.', 'd >= 40', 'The shadow shrinks towards the size of the object.')], 'Light travels in straight lines, and an object blocks it to make a shadow.')
ECL_S = ('eclipse', {}, 'Make a solar eclipse', [t('Put the Moon between the Sun and the Earth.', 'moon == 180', 'The shadow of the Moon falls on the Earth: a solar eclipse.')], 'A solar eclipse happens when the Moon is between the Sun and the Earth.')
ECL_L = ('eclipse', {}, 'Make a lunar eclipse', [t('Put the Moon behind the Earth.', 'moon == 0', 'The Moon moves into the shadow of the Earth: a lunar eclipse.')], 'A lunar eclipse happens when the Earth is between the Sun and the Moon.')
WAT = ('watercycle', {}, 'Follow a drop of water', [t('Go to the clouds.', 'step == 2', 'Vapour cools high up and condenses.'), t('Make it rain.', 'step == 3', 'Heavy drops fall.'), t('Bring it back to the sea.', 'step == 4', 'Then the cycle begins again.')], 'Water keeps moving between the sea, the air and the land.')
NEU = ('neutral', {}, 'Neutralise an acid', [t('Add base until it is neutral.', 'acid == base and acid == 4', 'Acid and base have cancelled each other out.'), t('Add one more drop of base.', 'base == acid + 1', 'Now it is basic.')], 'An acid and a base can neutralise each other.')
MAP = {
 'mathematics-g6': {(1, 2): PAT('odd', 'Grow the odd numbers', ('Go to term 5.', 'n == 5', 'The 5th odd number is 9.'), ('Go to term 8.', 'n == 8', 'Each term has two more dots.'), 'Odd numbers grow by 2.'),
  (1, 3): PAT('triangle', 'Grow a triangle of dots', ('Go to term 4.', 'n == 4', '1 + 2 + 3 + 4 = 10 dots.'), ('Go to term 6.', 'n == 6', 'Each new row is one dot longer: 21 dots.'), 'Triangular numbers add one more row each time.'),
  (1, 5): PAT('square', 'Grow a square of dots', ('Go to term 4.', 'n == 4', '4 rows of 4 make 16.'), ('Go to term 7.', 'n == 7', '7 rows of 7 make 49.'), 'Square numbers are rows times the same number of columns.'),
  (2, 2): ANGLE, (2, 4): ANGLE, (2, 5): ANGLE2, (2, 6): ANGLE2, (6, 1): RECT_P, (6, 3): RECT_A, (6, 6): RECT_C, (7, 1): FRAC, (7, 4): FRAC_MIX, (7, 5): FRAC_EQ, (10, 2): INT, (10, 3): INT, (10, 5): INT, (4, 3): BAR, (4, 4): BAR, (9, 2): SYM, (9, 4): ROT, (9, 5): ROT},
 'mathematics-g7': {(8, 1): FRAC, (10, 1): INT, (15, 1): BAL, (15, 3): BAL, (15, 4): BAL, (3, 2): DEC, (3, 3): DEC, (3, 5): DEC},
 'science': {(4, 2): MAG, (8, 1): PART_M, (8, 3): PART_S, (8, 5): WAT},
 'science-g7': {(3, 4): CIR, (3, 5): CIR2, (8, 3): PEN, (11, 4): REF, (12, 1): DAY, (12, 2): DAY, (12, 4): SEA, (2, 5): NEU, (2, 6): NEU, (7, 5): WAT, (8, 5): SPD, (8, 6): SPD, (11, 3): SHD, (12, 5): ECL_S, (12, 6): ECL_L},
 'sst6': {(1, 2): SCALE, (1, 3): LAT, (1, 4): LAT, (1, 5): LON, (1, 7): TZ, (1, 8): TZ, (4, 2): TL},   # chapter 1's built lessons are numbered 1 to 8, not as in its facts file
}
added = 0
for book, lessons in MAP.items():
    for (ch, k), (widget, params, title, tasks, take) in lessons.items():
        with tempfile.NamedTemporaryFile('w', suffix='.json', delete=False) as f: json.dump({'widget': widget, 'params': params, 'tasks': tasks}, f)
        r = json.loads(subprocess.run(['node', f'{HERE}/explore-check.mjs', f.name], capture_output=True, text=True).stdout); os.unlink(f.name)
        if not r['ok']: print('REJECTED', book, ch, k, widget, r['why']); continue
        p = f'{ROOT}/work/{book}/ch{ch:02d}/explore.json'
        d = json.load(open(p)) if os.path.exists(p) else {}
        if (d.get(str(k)) or {}).get('widget'): continue
        d[str(k)] = {'widget': widget, 'params': params, 'title': title, 'tasks': tasks, 'takeaway': take}
        json.dump(d, open(p, 'w'), indent=1, ensure_ascii=False); added += 1
print('simulations added:', added)
